"""Meeting insights generated by an LLM on Groq."""

from __future__ import annotations

import logging
import uuid
from collections.abc import Sequence
from datetime import UTC, datetime

import groq
from groq import AsyncGroq
from groq.types.chat import ChatCompletionMessageParam
from pydantic import BaseModel, Field, ValidationError

from app.core.config import settings
from app.models.schemas import MeetingInsights, TranscriptSegment

logger = logging.getLogger(__name__)

SYSTEM_PROMPT = """You are an expert meeting analyst.
Given a meeting transcript, extract structured insights.
Return ONLY valid JSON with exactly these fields:
{
  "summary": "2-3 sentence paragraph summarizing the meeting",
  "action_items": ["action item 1", "action item 2", ...],
  "decisions": ["decision 1", "decision 2", ...],
  "questions_raised": ["question 1", "question 2", ...],
  "follow_up_email": "A professional follow-up email draft with subject line and body"
}
Every list item must be a plain string. Be specific and concise. If a category has no items,
return an empty array. Long transcripts may have a marked gap in the middle; do not guess what
was said there."""

CORRECTION_PROMPT = (
    "That reply was not a JSON object with the required fields and types. "
    "Reply again with only the JSON object."
)

OMISSION_MARKER = "[... {count} transcript lines omitted to fit the model's context ...]"
# Share of the character budget kept from the start of the meeting; the rest
# comes from the end, where decisions and action items tend to be.
HEAD_SHARE = 1 / 3


class AIServiceError(Exception):
    """Insight generation failed. Messages are for logs, not for API clients."""


class AINotConfiguredError(AIServiceError):
    """GROQ_API_KEY is not set."""


class AIUpstreamError(AIServiceError):
    """Groq could not be reached or rejected the request."""


class AIResponseError(AIServiceError):
    """The model's reply could not be used, even after a retry."""


class _InsightsContent(BaseModel):
    """What the model must return."""

    summary: str = Field(min_length=1)
    action_items: list[str] = Field(default_factory=list)
    decisions: list[str] = Field(default_factory=list)
    questions_raised: list[str] = Field(default_factory=list)
    follow_up_email: str


_client: AsyncGroq | None = None


def _get_client() -> AsyncGroq:
    """The process-wide Groq client (it keeps a connection pool)."""
    global _client
    if _client is None:
        _client = AsyncGroq(
            api_key=settings.groq_api_key,
            timeout=settings.groq_timeout_seconds,
            max_retries=1,
        )
    return _client


async def close_client() -> None:
    global _client
    client, _client = _client, None
    if client is not None:
        await client.close()


def _format_timestamp(seconds: float) -> str:
    minutes, secs = divmod(int(seconds), 60)
    hours, minutes = divmod(minutes, 60)
    return f"{hours}:{minutes:02d}:{secs:02d}" if hours else f"{minutes:02d}:{secs:02d}"


def build_transcript(segments: Sequence[TranscriptSegment], max_chars: int) -> tuple[str, int]:
    """Render segments as ``[mm:ss] Speaker: text`` lines within ``max_chars``.

    Keeps whole lines from the start and the end of the meeting and replaces the
    middle with a marker. Returns the text and the number of omitted lines.
    """
    lines = [f"[{_format_timestamp(s.timestamp)}] {s.speaker}: {s.text}" for s in segments]
    text = "\n".join(lines)
    if len(text) <= max_chars:
        return text, 0

    budget = max_chars - len(OMISSION_MARKER.format(count=len(lines))) - 2
    head: list[str] = []
    used = 0
    for line in lines:
        if used + len(line) + 1 > budget * HEAD_SHARE:
            break
        head.append(line)
        used += len(line) + 1
    tail: list[str] = []
    for line in reversed(lines[len(head) :]):
        if used + len(line) + 1 > budget:
            break
        tail.append(line)
        used += len(line) + 1
    tail.reverse()
    omitted = len(lines) - len(head) - len(tail)
    marker = OMISSION_MARKER.format(count=omitted)
    return "\n".join([*head, marker, *tail]), omitted


async def generate_insights(
    meeting_id: str,
    meeting_title: str,
    segments: Sequence[TranscriptSegment],
) -> MeetingInsights:
    if not settings.groq_api_key:
        raise AINotConfiguredError("GROQ_API_KEY is not set")
    final_segments = [s for s in segments if s.is_final]
    if not final_segments:
        raise ValueError("no final transcript segments to analyze")

    transcript, omitted = build_transcript(final_segments, settings.ai_max_transcript_chars)
    if omitted:
        logger.warning(
            "Transcript of meeting %s exceeds %d characters; omitted %d of %d lines",
            meeting_id,
            settings.ai_max_transcript_chars,
            omitted,
            len(final_segments),
        )

    messages: list[ChatCompletionMessageParam] = [
        {"role": "system", "content": SYSTEM_PROMPT},
        {
            "role": "user",
            "content": (
                f"Meeting Title: {meeting_title}\n\nTranscript:\n{transcript}\n\n"
                "Analyze this meeting and return the JSON insights."
            ),
        },
    ]
    logger.info(
        "Generating insights for meeting %s (%d segments) with %s",
        meeting_id,
        len(final_segments),
        settings.groq_model,
    )
    content = await _request_insights(meeting_id, messages)
    return MeetingInsights(
        id=str(uuid.uuid4()),
        meeting_id=meeting_id,
        generated_at=datetime.now(UTC),
        **content.model_dump(),
    )


async def _request_insights(
    meeting_id: str, messages: list[ChatCompletionMessageParam]
) -> _InsightsContent:
    """Ask for insights; if the reply is unusable, say so and ask once more."""
    reply = await _complete(messages)
    try:
        return _InsightsContent.model_validate_json(reply or "")
    except ValidationError as error:
        logger.warning(
            "Model reply for meeting %s failed validation (%d errors); retrying once",
            meeting_id,
            error.error_count(),
        )
    retry_messages: list[ChatCompletionMessageParam] = [
        *messages,
        {"role": "assistant", "content": reply or ""},
        {"role": "user", "content": CORRECTION_PROMPT},
    ]
    reply = await _complete(retry_messages)
    try:
        return _InsightsContent.model_validate_json(reply or "")
    except ValidationError as error:
        raise AIResponseError(f"model reply failed validation twice: {error}") from error


async def _complete(messages: list[ChatCompletionMessageParam]) -> str | None:
    """Run one chat completion in JSON mode; None if Groq rejected the JSON it generated."""
    effort = settings.groq_reasoning_effort
    reasoning = {"reasoning_effort": effort} if effort else {}
    try:
        response = await _get_client().chat.completions.create(
            model=settings.groq_model,
            messages=messages,
            temperature=settings.groq_temperature,
            max_tokens=settings.groq_max_tokens,
            response_format={"type": "json_object"},
            **reasoning,
        )
    except groq.BadRequestError as error:
        if _is_json_validation_failure(error):
            return None
        raise AIUpstreamError(f"Groq rejected the request: {error}") from error
    except groq.APIError as error:
        raise AIUpstreamError(f"Groq request failed: {error}") from error
    if not response.choices:
        return None
    return response.choices[0].message.content


def _is_json_validation_failure(error: groq.BadRequestError) -> bool:
    """Groq answers 400 ``json_validate_failed`` when JSON mode output is invalid."""
    body = error.body if isinstance(error.body, dict) else {}
    details = body.get("error", body)
    return isinstance(details, dict) and details.get("code") == "json_validate_failed"
